rollback.sql:
WITH execution_time AS (SELECT exec_time FROM tmp_execution_time)
DELETE FROM ${currency.table}
WHERE effective_from = (SELECT exec_time FROM execution_time);

WITH execution_time AS (SELECT exec_time FROM tmp_execution_time)
UPDATE ${currency.table}
SET effective_to = NULL,
    is_active = true
WHERE effective_to = (SELECT exec_time FROM execution_time);

DROP TABLE IF EXISTS tmp_execution_time;
